import json,re
from pathlib import Path
p=Path('work/kb/battle_annotations.json');d=json.loads(p.read_text(encoding='utf-8'))
def put(a,details,inp='',output='',confidence=None):
 r=d[f'47:{a:04X}'];r['details']=details
 r.pop('input',None);r.pop('output',None)
 if inp:r['input']=inp
 if output:r['output']=output
 if confidence:r['confidence']=confidence
