# Точное декодирование порядка соседей по INC/DEC смещений, без исполнения кода игры.
import sys
sys.path.insert(0,str(Path('work').resolve()))
from analyze import memory,decoder
mem=memory(47)
vecnames={(0,-1):'север',(-1,-1):'северо-запад',(1,-1):'северо-восток',(-1,0):'запад',(1,0):'восток',(-1,1):'юго-запад',(1,1):'юго-восток',(0,1):'юг'}
for a in [0xE67D,0xE6A2,0xE6C7,0xE6EC,0xE711,0xE736,0xE75B,0xE780]:
 v=[[0,0] for _ in range(8)]
 for i in decoder(mem).disassemble(a,a+37,'h'):
  m=re.match(r'(INC|DEC) \(IY\+\$(\w+)\)',i.operation)
  if m:
   off=int(m[2],16);row=off//3;dim=off%3-1;v[row][dim]+=1 if m[1]=='INC' else -1
 seq=', '.join(vecnames[tuple(x)] for x in v)
 put(a,'изменяет только координаты восьми троек E639, порядок обхода: '+seq+', север уменьшает строку, восток увеличивает столбец, процедура вызывается вычисленным RET из E5B0, завершается RET к E5E1','IY=E639, восемь координат равны исходной клетке','соседние координаты записаны, регистры не изменяются')
